    34	): ServerMemoryObservation {
    35		if (process.platform !== "linux") {
    36			return {
    37				iteration,
    38				phase,
    39				rssBytes: null,
    40				unavailableReason: `server RSS is unavailable on ${process.platform}`,
    41			};
    42		}
    43		if (pid === null) {
    44			return {
    45				iteration,
