    89	export async function createPerformanceHarness(
    90		mode: FixtureMode,
    91	): Promise<PerformanceHarness> {
    92		const stderrChunks: string[] = [];
    93		const transport = new StdioClientTransport({
    94			command: process.execPath,
    95			args: [
    96				"--import",
    97				resolve("tests/performance/child-fixture.mjs"),
    98				resolve("packages/node/dist/cli.mjs"),
    99			],
   100			cwd: process.cwd(),
   101			env: {
   102				...process.env,
   103				HEVY_API_KEY: PERFORMANCE_API_KEY,
   104				HEVY_PERFORMANCE_FIXTURE_MODE: mode,
   105				OTEL_COLLECTOR_TOKEN: "",
   106				SENTRY_DSN: "",
   107			},
   108			stderr: "pipe",
   109		});
   110		const stderr = transport.stderr as Readable | null;
   111		let resolveFixtureMarker: () => void = () => undefined;
   112		const fixtureMarkerSeen = new Promise<void>((resolvePromise) => {
   113			resolveFixtureMarker = resolvePromise;
   114		});
   115		let fixtureMarkerSearchTail = "";
   116		let fixtureMarkerFound = false;
   117		stderr?.setEncoding("utf8");
   118		stderr?.on("data", (chunk: string) => {
   119			stderrChunks.push(chunk);
   120			if (fixtureMarkerFound) return;
   121	
   122			const markerSearchBuffer = fixtureMarkerSearchTail + chunk;
   123			if (markerSearchBuffer.includes(FIXTURE_RESULT_PREFIX)) {
   124				fixtureMarkerFound = true;
   125				resolveFixtureMarker();
   126				return;
   127			}
   128			fixtureMarkerSearchTail = markerSearchBuffer.slice(
   129				-(FIXTURE_RESULT_PREFIX.length - 1),
   130			);
   131		});
   132	
   133		const client = new Client(
   134			{ name: "hevy-mcp-performance-client", version: "1.0.0" },
   135			{ capabilities: {} },
   136		);
   137	
   138		try {
   139			await client.connect(transport);
   140		} catch (error) {
   141			try {
   142				await client.close();
   143			} catch {
   144				// Preserve the connection error; scenario reporting records the failure.
   145			}
   146			if (stderr) await withTimeout(fixtureMarkerSeen);
   147			const detail = stderrChunks.join("").trim();
   148			throw new Error(
   149				`failed to initialize built CLI${detail ? `: ${detail}` : ""}`,
   150				{ cause: error },
   151			);
   152		}
   153	
   154		let closed = false;
   155		return {
   156			client,
   157			pid: transport.pid,
   158			async close() {
   159				if (closed) {
   160					throw new Error("performance harness was closed more than once");
   161				}
   162				closed = true;
   163				await client.close();
   164				if (stderr) await withTimeout(fixtureMarkerSeen);
   165				return parseFixtureResult(stderrChunks.join(""), mode);
   166			},
   167		};
   168	}
