 30	async function closeHarness(
 31		state: ScenarioState,
 32		harness: PerformanceHarness,
 33		iteration: number,
 34	) {
 35		state.serverMemory.push(
 36			observeServerRss(harness.pid, iteration, "scenario-complete"),
 37		);
 38		try {
 39			recordFixtureResult(state, iteration, await harness.close());
 40		} catch (error) {
 41			recordFailure(state, iteration, "cleanup", error);
 42		}
 43	}
