 45	async function runStartupScenario() {
 46		const state = createScenarioState(
 47			"startup-initialization",
 48			STARTUP_ITERATIONS,
 49			{
 50				description: "Startup plus MCP initialize p95 below 2 seconds",
 51				p95Milliseconds: 2_000,
 52				informationalOnly: true,
 53			},
 54		);
 55		const scenarioStartedAt = performance.now();
 56	
 57		for (let iteration = 1; iteration <= STARTUP_ITERATIONS; iteration += 1) {
 58			const startedAt = performance.now();
 59			let harness: PerformanceHarness | undefined;
 60			try {
 61				harness = await createPerformanceHarness("startup");
 62				state.durations.push(measuredDuration(startedAt));
 63				state.completedIterations += 1;
 64				state.serverMemory.push(
 65					observeServerRss(harness.pid, iteration, "initialized"),
 66				);
 67			} catch (error) {
 68				state.durations.push(measuredDuration(startedAt));
 69				recordFailure(state, iteration, "setup", error);
 70			}
 71			if (harness) await closeHarness(state, harness, iteration);
 72		}
 73	
 74		return finalizeScenario(state, measuredDuration(scenarioStartedAt));
 75	}
