110	export function percentile(values: number[], fraction: number) {
111		if (values.length === 0) {
112			throw new Error("Cannot calculate a percentile for an empty sample");
113		}
114		if (fraction <= 0 || fraction > 1) {
115			throw new Error("Percentile fraction must be greater than 0 and at most 1");
116		}
117	
118		const sorted = [...values].sort((left, right) => left - right);
119		const index = Math.ceil(fraction * sorted.length) - 1;
120		return sorted[index] ?? sorted[sorted.length - 1]!;
121	}
122	
123	export function summarizeDurations(values: number[]) {
124		return {
125			p50: percentile(values, 0.5),
126			p95: percentile(values, 0.95),
127			max: Math.max(...values),
128		};
129	}
