136			heapUsedBeforeBytes: before.heapUsed,
137			heapUsedAfterBytes: after.heapUsed,
138			heapUsedDeltaBytes: after.heapUsed - before.heapUsed,
139			rssBeforeBytes: before.rss,
140			rssAfterBytes: after.rss,
141			rssDeltaBytes: after.rss - before.rss,
142		};
143	}
