 31	export function parseFixtureResult(stderr: string, expectedMode: FixtureMode) {
 32		const markers = stderr
 33			.split(/\r?\n/u)
 34			.filter((line) => line.startsWith(FIXTURE_RESULT_PREFIX));
 35		if (markers.length !== 1) {
 36			throw new Error(
 37				`expected exactly one child fixture result marker, found ${markers.length}`,
 38			);
 39		}
 40	
 41		let parsed: unknown;
 42		try {
 43			parsed = JSON.parse(markers[0]!.slice(FIXTURE_RESULT_PREFIX.length));
 44		} catch (error) {
 45			throw new Error("child fixture result marker contained malformed JSON", {
 46				cause: error,
 47			});
 48		}
 49	
 50		const result = fixtureResultSchema.parse(parsed);
 51		if (result.mode !== expectedMode) {
 52			throw new Error(
 53				`child fixture mode mismatch: expected ${expectedMode}, received ${result.mode}`,
 54			);
 55		}
 56		return result;
 57	}
