124	export function parseArgs(args: string[]): CliOptions {
125		const options: CliOptions = { help: false, enforceBudget: false };
126	
127		for (let index = 0; index < args.length; index += 1) {
128			const argument = args[index];
129			if (argument === "--help" || argument === "-h") {
130				options.help = true;
131				continue;
132			}
133			if (argument === "--enforce-budget") {
134				options.enforceBudget = true;
135				continue;
136			}
137	
138			const optionKey =
139				argument === "--output" || argument === "-o"
140					? "outputPath"
141					: argument === "--baseline"
142						? "baselinePath"
143						: argument === "--markdown"
144							? "markdownPath"
145							: undefined;
146	
147			if (!optionKey) {
148				throw new Error(`Unknown option: ${argument ?? ""}`);
149			}
150	
151			const value = args[index + 1];
152			if (!value || OPTION_TOKENS.has(value)) {
153				throw new Error(`Missing value for ${argument}`);
154			}
155	
156			options[optionKey] = value;
157			index += 1;
158		}
159	
160		return options;
161	}
