168	export function getTargetStatus(
169		value: number,
170		target: number,
171		inclusive: boolean,
172	): TargetStatus {
173		return inclusive
174			? value <= target
175				? "withinTarget"
176				: "aboveTarget"
177			: value < target
178				? "withinTarget"
179				: "aboveTarget";
180	}
