197	function measureToolComponentTokens(
198		tool: Tool,
199		encoder: EncoderLike,
200	): ComponentTokenTotals {
201		const values = {
202			name: tool.name,
203			description: tool.description,
204			inputSchema: tool.inputSchema,
205			outputSchema: tool.outputSchema,
206			annotations: tool.annotations,
207		};
208		const componentTokens = emptyComponentTokenTotals();
209		for (const component of TOOL_COMPONENTS) {
210			componentTokens[component] = countEncodedTokens(values[component], encoder);
211		}
212		return componentTokens;
213	}
214	
215	function sumComponentTokenTotals(
216		tools: Array<Pick<ToolTokenCost, "componentTokens">>,
217	): ComponentTokenTotals {
218		const totals = emptyComponentTokenTotals();
219		for (const tool of tools) {
220			for (const component of TOOL_COMPONENTS) {
221				totals[component] += tool.componentTokens[component];
222			}
223		}
224		return totals;
225	}
