227	export function measureTokenPayload(
228		tools: Tool[],
229		encoder: EncoderLike,
230	): TokenCostReport {
231		const totalTokens = countEncodedTokens({ tools }, encoder);
232		const toolCosts = tools
233			.map((tool) => {
234				const componentTokens = measureToolComponentTokens(tool, encoder);
235				return {
236					name: tool.name,
237					tokens: countEncodedTokens(tool, encoder),
238					componentTokens,
239				};
240			})
241			.sort((left, right) => {
242				if (right.tokens !== left.tokens) return right.tokens - left.tokens;
243				return left.name < right.name ? -1 : left.name > right.name ? 1 : 0;
244			});
245		const toolCount = tools.length;
246		const averageTokensPerTool = round(
247			toolCount === 0 ? 0 : totalTokens / toolCount,
248		);
249	
250		return {
251			schemaVersion: TOKEN_COST_SCHEMA_VERSION,
252			encoding: TOKEN_ENCODING,
253			measurementScope: MEASUREMENT_SCOPE,
254			toolCount,
255			totalTokens,
256			averageTokensPerTool,
257			componentTokens: sumComponentTokenTotals(toolCosts),
258			targets: {
259				toolCount: {
260					maximumInclusive: TOOL_COUNT_TARGET,
261					status: getTargetStatus(toolCount, TOOL_COUNT_TARGET, true),
262					enforced: false,
263				},
264				averageTokensPerTool: {
265					maximumExclusive: AVERAGE_TOKEN_TARGET,
266					status: getTargetStatus(
267						averageTokensPerTool,
268						AVERAGE_TOKEN_TARGET,
269						false,
270					),
271					enforced: false,
272				},
273				totalTokens: {
274					maximumInclusive: TOTAL_TOKEN_BUDGET,
275					status: getTargetStatus(totalTokens, TOTAL_TOKEN_BUDGET, true),
276					enforced: true,
277				},
278			},
279			tools: toolCosts.map((tool) => ({
280				...tool,
281				percentageOfTotal: round(
282					totalTokens === 0 ? 0 : (tool.tokens / totalTokens) * 100,
283				),
284			})),
285		};
286	}
