288	export function compareReports(
289		current: TokenCostReport,
290		baseline: TokenCostReport,
291	): BaselineComparison {
292		const currentByName = new Map(
293			current.tools.map((tool) => [tool.name, tool.tokens]),
294		);
295		const baselineByName = new Map(
296			baseline.tools.map((tool) => [tool.name, tool.tokens]),
297		);
298		const names = [
299			...new Set([...currentByName.keys(), ...baselineByName.keys()]),
300		];
301	
302		const toolDeltas = names
303			.map((name) => {
304				const currentTokens = currentByName.get(name);
305				const baselineTokens = baselineByName.get(name);
306				return {
307					name,
308					currentTokens,
309					baselineTokens,
310					delta: (currentTokens ?? 0) - (baselineTokens ?? 0),
311				};
312			})
313			.sort((left, right) => {
314				const absoluteDelta = Math.abs(right.delta) - Math.abs(left.delta);
315				if (absoluteDelta !== 0) return absoluteDelta;
316				return left.name < right.name ? -1 : left.name > right.name ? 1 : 0;
317			});
318	
319		const componentTokenDeltas = emptyComponentTokenTotals();
320		for (const component of TOOL_COMPONENTS) {
321			componentTokenDeltas[component] =
322				current.componentTokens[component] - baseline.componentTokens[component];
323		}
324		return {
325			baseline,
326			totalTokensDelta: current.totalTokens - baseline.totalTokens,
327			toolCountDelta: current.toolCount - baseline.toolCount,
328			averageTokensPerToolDelta: round(
329				current.averageTokensPerTool - baseline.averageTokensPerTool,
330			),
331			componentTokenDeltas,
332			toolDeltas,
333		};
334	}
