336	function hasComponentTokenTotals(
337		value: unknown,
338	): value is ComponentTokenTotals {
339		if (!value || typeof value !== "object") return false;
340		const candidate = value as Record<string, unknown>;
341		return TOOL_COMPONENTS.every(
342			(component) => typeof candidate[component] === "number",
343		);
344	}
