346	export function isCompatibleBaseline(value: unknown): value is TokenCostReport {
347		if (!value || typeof value !== "object") return false;
348		const candidate = value as Partial<TokenCostReport>;
349		return (
350			candidate.schemaVersion === TOKEN_COST_SCHEMA_VERSION &&
351			candidate.encoding === TOKEN_ENCODING &&
352			candidate.measurementScope === MEASUREMENT_SCOPE &&
353			typeof candidate.toolCount === "number" &&
354			typeof candidate.totalTokens === "number" &&
355			typeof candidate.averageTokensPerTool === "number" &&
356			hasComponentTokenTotals(candidate.componentTokens) &&
357			Array.isArray(candidate.tools) &&
358			candidate.tools.every(
359				(tool) =>
360					typeof tool?.name === "string" &&
361					typeof tool.tokens === "number" &&
362					hasComponentTokenTotals(tool.componentTokens),
363			)
364		);
365	}
