   514	export function formatTable(report: TokenCostReport): string {
   515		const headers = ["Tool", ...TOOL_COMPONENTS, "Total", "Share"];
   516		const rows = report.tools.map((tool) => [
   517			tool.name,
   518			...TOOL_COMPONENTS.map((component) =>
   519				String(tool.componentTokens[component]),
   520			),
   521			String(tool.tokens),
   522			`${tool.percentageOfTotal}%`,
   523		]);
   524		const widths = headers.map((header, index) =>
   525			Math.max(header.length, ...rows.map((row) => row[index]?.length ?? 0)),
   526		);
   527		const formatRow = (values: string[]) =>
   528			values
   529				.map((value, index) =>
   530					index === 0
   531						? value.padEnd(widths[index] ?? value.length)
   532						: value.padStart(widths[index] ?? value.length),
   533				)
   534				.join("  ");
   535		const divider = widths.map((width) => "-".repeat(width)).join("  ");
   536		return [
   537			`MCP tool token cost (${report.encoding})`,
   538			`Tools: ${report.toolCount} | Total: ${report.totalTokens} | Average: ${report.averageTokensPerTool}`,
   539			[
   540				"Component totals: ",
   541				TOOL_COMPONENTS.map(
   542					(component) => `${component}=${report.componentTokens[component]}`,
   543				).join(" | "),
   544			].join(""),
   545			formatRow(headers),
   546			divider,
   547			...rows.map(formatRow),
   548			"",
   549			[
   550				`Targets: tools ≤ ${report.targets.toolCount.maximumInclusive}; average < `,
   551				`${report.targets.averageTokensPerTool.maximumExclusive} tokens/tool; total ≤ ${report.targets.totalTokens.maximumInclusive} tokens (enforced).`,
   552			].join(""),
   553			"Per-tool counts exclude the shared { tools } envelope punctuation.",
   554		].join("\n");
   555	}
