   124					const provided = args[optionIndex] as HevyRequestOptions | undefined;
   125					const merged: HevyRequestOptions = {
   126						...provided,
   127						...control,
   128					};
   129					args[optionIndex] = merged;
   130					return Reflect.apply(value, target, args);
   131				};
