 625	export function calculateDuration(
 626		startTime: string | number | null | undefined,
 627		endTime: string | number | null | undefined,
 628	): string {
 629		if (!startTime || !endTime) return "Unknown duration";
 630	
 631		try {
 632			const start = new Date(startTime);
 633			const end = new Date(endTime);
 634			if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) {
 635				return "Unknown duration";
 636			}
 637			const durationMs = end.getTime() - start.getTime();
 638			if (durationMs < 0) {
 639				return "Invalid duration (end time before start time)";
 640			}
 641			const hours = Math.floor(durationMs / (1000 * 60 * 60));
 642			const minutes = Math.floor((durationMs % (1000 * 60 * 60)) / (1000 * 60));
 643			const seconds = Math.floor((durationMs % (1000 * 60)) / 1000);
 644			return `${hours}h ${minutes}m ${seconds}s`;
 645		} catch (error) {
 646			console.error(
 647				"Error calculating duration",
 648				createSafeErrorDiagnostic(error),
 649			);
 650			return "Unknown duration";
 651		}
 652	}
