   161			"error.type": errorType,
   162			"error.category": diagnostic?.category ?? "UnknownError",
   163			...(diagnostic?.code ? { "error.code": diagnostic.code } : {}),
   164			...(diagnostic?.status !== undefined
   165				? { "http.response.status_code": diagnostic.status }
   166				: {}),
   167			...(diagnostic?.method ? { "http.request.method": diagnostic.method } : {}),
