   175	function setSafeErrorAttributes(
   176		span: Span,
   177		invocation: SafeToolInvocation,
   178		completion: SafeToolCompletion,
   179	): string {
   180		const errorType = completion.errorType ?? "UNKNOWN_ERROR";
   181		const attributes = createFailureAttributes(invocation, completion, errorType);
   182		if (completion.error) {
   183			span.addEvent("mcp.tool.failure", attributes);
   184		}
   185		for (const [key, value] of Object.entries(
   186			projectExecutionAttributes(createExecutionProjection(completion.error)),
   187		)) {
   188			span.setAttribute(key, value);
   189		}
   190		span.setAttribute("error.type", errorType);
   191		return errorType;
