   202	/** Node-only adapter from core's privacy-safe observation contract to OTel. */
   203	export function createNodeToolObserver(): ToolObserver {
   204		return {
   205			start(invocation): ToolObservationScope {
   206				const startedAt = Date.now();
   207				const clientAttributes = recordMcpToolInvocation();
   208				const metrics = metricAttributes(invocation, clientAttributes);
   209				bestEffort(() => toolInvocations.add(1, metrics));
   210				let completion: SafeToolCompletion | undefined;
   211				let activeSpan: Span | undefined;
   212				let thrownError: unknown;
   213				return {
   214					run<T>(operation: () => Promise<T>): Promise<T> {
   215						return tracer.startActiveSpan(
   216							`mcp.tool.${invocation.name}`,
   217							{ attributes: createAttributes(invocation) },
   218							async (span) => {
   219								activeSpan = span;
   220								try {
   221									return await operation();
   222								} catch (error) {
   223									thrownError = error;
   224									throw error;
   225								}
   226							},
   227						);
   228					},
   229					finish(nextCompletion) {
   230						if (completion) return;
   231						completion = nextCompletion;
   232						const durationMs = Math.max(
   233							0,
   234							nextCompletion.durationMs || Date.now() - startedAt,
   235						);
   236						const isError = nextCompletion.outcome !== "success";
   237						if (isError) bestEffort(recordMcpToolFailure);
   238						bestEffort(() =>
   239							toolOutcomes.add(1, {
   240								...metrics,
   241								outcome: nextCompletion.outcome,
   242							}),
   243						);
   244						let errorType: string | undefined;
   245						try {
   246							if (activeSpan) {
   247								activeSpan.setStatus({
   248									code:
   249										nextCompletion.outcome === "success" &&
   250										nextCompletion.result?.isError !== true
   251											? SpanStatusCode.OK
   252											: SpanStatusCode.ERROR,
   253								});
   254								activeSpan.setAttribute(
   255									"mcp.tool.outcome",
   256									nextCompletion.outcome,
   257								);
   258								setResultAttributes(activeSpan, nextCompletion);
   259								if (nextCompletion.outcome === "thrown_error") {
   260									errorType = setSafeErrorAttributes(
   261										activeSpan,
   262										invocation,
   263										nextCompletion,
   264									);
   265								}
   266								if (nextCompletion.outcome === "returned_error") {
   267									const execution = projectExecutionAttributes(
   268										nextCompletion.errorOutcome,
   269									);
   270									activeSpan.addEvent("mcp.tool.failure", {
   271										"mcp.tool.name": invocation.name,
   272										"error.type": "UNKNOWN_ERROR",
   273										"error.category": "McpToolReturnedError",
   274										"error.code": "MCP_TOOL_RETURNED_ERROR",
   275										...execution,
   276									});
   277									activeSpan.setAttribute("error.type", "UNKNOWN_ERROR");
   278									for (const [key, value] of Object.entries(execution)) {
   279										activeSpan.setAttribute(key, value);
   280									}
   281								}
   282							}
   283						} catch {
   284							// Instrumentation metadata must never alter the MCP response.
   285						} finally {
   286							if (nextCompletion.outcome === "thrown_error") {
   287								const error =
   288									thrownError ??
   289									new Error(nextCompletion.error?.category ?? errorType);
   290								bestEffort(() =>
   291									captureFailure(error, {
   292										kind: invocation.kind === "prompt" ? "prompt" : "tool",
   293										attributes: createFailureAttributes(
   294											invocation,
   295											nextCompletion,
   296											errorType,
   297										),
   298										span: activeSpan,
   299									}),
   300								);
   301								bestEffort(() =>
   302									toolErrors.add(1, {
   303										...metrics,
   304										error_type:
   305											errorType ?? nextCompletion.errorType ?? "UNKNOWN_ERROR",
   306									}),
   307								);
   308							}
   309							bestEffort(() =>
   310								toolDuration.record(durationMs, {
   311									...metrics,
   312									is_error: String(isError),
   313									outcome: nextCompletion.outcome,
   314								}),
   315							);
   316							bestEffort(() => activeSpan?.end());
   317							activeSpan = undefined;
   318						}
   319					},
   320				};
   321			},
   322		};
   323	}
