  1	export interface PageResult<T> {
  2		items: readonly T[];
  3		pageCount?: number;
  4	}
  5	
  6	export type PageLoader<T> = (
  7		page: number,
  8		pageSize: number,
  9	) => PageResult<T> | PromiseLike<PageResult<T>>;
 10	
 11	export async function fetchAllPages<T>(
 12		loader: PageLoader<T>,
 13		pageSize: number,
 14	): Promise<T[]> {
 15		const items: T[] = [];
 16		let page = 1;
 17	
 18		while (true) {
 19			const result = await loader(page, pageSize);
 20			if (result.items.length === 0) {
 21				return items;
 22			}
 23			// The current page has already been appended before this boundary check.
 24			items.push(...result.items);
 25			const pageCount = result.pageCount;
 26			if (
 27				typeof pageCount !== "number" ||
 28				!Number.isSafeInteger(pageCount) ||
 29				pageCount <= page
 30			) {
 31				return items;
 32			}
 33			page += 1;
 34		}
 35	}
