    76	export function defineStructuredResponseContract<
    77		const TShape extends OutputShape,
    78		TData,
    79	>(
    80		definition: StructuredContractDefinition<TData, TShape>,
    81	): StructuredResponseContract<TData, TShape> {
    82		return {
    83			outputSchema: definition.outputSchema,
    84			render(data) {
    85				const structuredContent = z
    86					.object(definition.outputSchema)
    87					.parse(definition.normalize(data));
    88				const text =
    89					definition.text?.(data, structuredContent) ??
    90					jsonText(definition.legacyJson(structuredContent));
    91				const additionalText =
    92					definition.additionalText?.(data, structuredContent) ?? [];
    93				const response: McpToolResponse = {
    94					content: [textContent(text), ...additionalText.map(textContent)],
    95					structuredContent,
    96				};
    97				attachResultTelemetry(response, definition.telemetry?.(data));
    98				return response;
    99			},
   100		};
   101	}
